# Cell
import pandas as pd
from pathlib import Path
import json

def load_tables(db_path):
    """Load all pickle files from directory"""
    tables = {}
    db_path = Path(db_path)
    for file_path in db_path.glob("*.pkl"):
        table_name = file_path.stem
        tables[table_name] = pd.read_pickle(file_path)
    return tables

def get_record_essentials(tables, record_id):
    df_record = tables['Record'][tables['Record']['id'] == record_id]
    df_cell = tables['Cell'][tables['Cell']['record_id'] == record_id]
    
    experiment_id = df_record["experiment_id"].iloc[0]
    df_experiment = tables['Experiment'][tables['Experiment']['id'] == experiment_id]
    
    mouse_id = df_experiment["mouse_id"].iloc[0]
    df_mouse = tables['Mouse'][tables['Mouse']['id'] == mouse_id]
    
    tool_id = df_record["tool_id"].iloc[0]
    df_tool = tables['Tool'][tables['Tool']['id'] == tool_id]
    
    df_map = tables['Map'][tables['Map']['tool_id'] == tool_id]
    
    return {
        "record": df_record,
        "cell": df_cell,
        "experiment": df_experiment,
        "mouse": df_mouse,
        "tool": df_tool,
        "map": df_map
    }

def get_stim_params(tables, stim_hashes):
    if not isinstance(stim_hashes, list):
        stim_hashes = [stim_hashes]
        
    df_stimulus = tables['Stimulus']
    df_compiled = tables['Compiled']
    df_compiled_param = tables['Compiled_Parameter']
    df_parameter = tables['Parameter']
    
    merged = (df_stimulus.merge(df_compiled, 
                              left_on='id', 
                              right_on='stimulus_id', 
                              suffixes=('', '_compiled'))
             .merge(df_compiled_param, 
                   left_on='id_compiled', 
                   right_on='compiled_id', 
                   how='left')
             .merge(df_parameter, 
                   left_on='parameter_id', 
                   right_on='id', 
                   suffixes=('', '_parameter')))
    
    result = merged[merged['hash'].isin(stim_hashes)]
    
    columns = {
        'name': 'stim_name',
        'description': 'description',
        'barcode': 'barcode',
        'comment': 'stim_comment',
        'stimulus_id': 'stimulus_id',
        'screen_id': 'screen_id',
        'hash': 'hash',
        'date': 'date_compiled',
        'comment_compiled': 'compiled_comment',
        'id_compiled': 'compiled_id',
        'parameter_id': 'parameter_id',
        'name_parameter': 'param_name',
        'value': 'param_value'
    }
    
    return result.rename(columns=columns)[columns.values()]

def get_table(tables, table_name):
    return tables[table_name].copy()

def stim_param_to_dict(param_df, md5):
    param_dict = {}
    stim_mask = param_df["hash"] == md5
    for _, row in param_df[stim_mask][["param_name", "param_value"]].iterrows():
        try:
            param = json.loads(row["param_value"])
        except:
            param = row["param_value"]
        param_dict[row["param_name"]] = param
    return param_dict